  c.lightning = approach(c.lightning, t.lightning, T.lightning * k, dt);
  c.fog = approach(c.fog, t.fog, T.fog * k, dt);
  c.closed = t.closed;
  s.wet = approach(s.wet, c.rain, c.rain > s.wet ? T.rain : T.wet, dt);   // ướt nhanh, khô chậm
